INSERT INTO public.quran_tafsir (id,surah_id,ayah_number,tafsir_ar,author,created_at,updated_at,source_url,retrieved_at) SELECT gen_random_uuid(),37,61,'لمثل هذا النعيم الكامل، والخلود الدائم، والفوز العظيم، فليعمل العاملون في الدنيا؛ ليصيروا إليه في الآخرة.','التفسير الميسر',now(),now(),'https://api.alquran.cloud/v1/surah/37/ar.muyassar','2026-08-17T00:00:00+00:00' WHERE EXISTS (SELECT 1 FROM public.quran_surahs WHERE id=37) ON CONFLICT (surah_id,ayah_number,author) DO UPDATE SET tafsir_ar=excluded.tafsir_ar,updated_at=now(),source_url=excluded.source_url,retrieved_at=excluded.retrieved_at;
INSERT INTO public.quran_tafsir (id,surah_id,ayah_number,tafsir_ar,author,created_at,updated_at,source_url,retrieved_at) SELECT gen_random_uuid(),37,62,'أذلك الذي سبق وصفه مِن نعيم الجنة خير ضيافة وعطاء من الله، أم شجرة الزقوم الخبيثة الملعونة، طعام أهل النار؟','التفسير الميسر',now(),now(),'https://api.alquran.cloud/v1/surah/37/ar.muyassar','2026-08-17T00:00:00+00:00' WHERE EXISTS (SELECT 1 FROM public.quran_surahs WHERE id=37) ON CONFLICT (surah_id,ayah_number,author) DO UPDATE SET tafsir_ar=excluded.tafsir_ar,updated_at=now(),source_url=excluded.source_url,retrieved_at=excluded.retrieved_at;
INSERT INTO public.quran_tafsir (id,surah_id,ayah_number,tafsir_ar,author,created_at,updated_at,source_url,retrieved_at) SELECT gen_random_uuid(),37,63,'إنا جعلناها فتنة افتتن بها الظالمون لأنفسهم بالكفر والمعاصي، وقالوا مستنكرين: إن صاحبكم ينبئكم أن في النار شجرة، والنار تأكل الشجر.','التفسير الميسر',now(),now(),'https://api.alquran.cloud/v1/surah/37/ar.muyassar','2026-08-17T00:00:00+00:00' WHERE EXISTS (SELECT 1 FROM public.quran_surahs WHERE id=37) ON CONFLICT (surah_id,ayah_number,author) DO UPDATE SET tafsir_ar=excluded.tafsir_ar,updated_at=now(),source_url=excluded.source_url,retrieved_at=excluded.retrieved_at;
INSERT INTO public.quran_tafsir (id,surah_id,ayah_number,tafsir_ar,author,created_at,updated_at,source_url,retrieved_at) SELECT gen_random_uuid(),37,64,'إنها شجرة تنبت في قعر جهنم، ثمرها قبيح المنظر كأنه رؤوس الشياطين، فإذا كانت كذلك فلا تَسْألْ بعد هذا عن طعمها، فإن المشركين لآكلون من تلك الشجرة فمالئون منها بطونهم. ثم إنهم بعد الأكل منها لشاربون شرابًا خليطًا قبيحًا حارًّا، ثم إن مردَّهم بعد هذا العذاب إلى عذاب النار.','التفسير الميسر',now(),now(),'https://api.alquran.cloud/v1/surah/37/ar.muyassar','2026-08-17T00:00:00+00:00' WHERE EXISTS (SELECT 1 FROM public.quran_surahs WHERE id=37) ON CONFLICT (surah_id,ayah_number,author) DO UPDATE SET tafsir_ar=excluded.tafsir_ar,updated_at=now(),source_url=excluded.source_url,retrieved_at=excluded.retrieved_at;
